package com.dramastudio.engine;
import com.dramastudio.template.NodeCatalog; import java.util.*; import org.springframework.stereotype.Component;
@Component public class DagValidator {
 public record Issue(String code,String nodeId,String message,List<String> missingRequirements){}
 private boolean compatible(String output,String input){return input.equals("ANY")||output.equals(input)||(output.equals("IMAGE_ASSET_LIST")&&input.equals("ASSET_REF_LIST"));}
@SuppressWarnings("unchecked") public List<Issue> validate(Map<String,Object> canvas){var issues=new ArrayList<Issue>();List<Map<String,Object>> nodes=(List<Map<String,Object>>)canvas.getOrDefault("nodes",List.of()),edges=(List<Map<String,Object>>)canvas.getOrDefault("edges",List.of());var ids=new HashSet<String>();var types=new HashMap<String,String>();for(var n:nodes){String id=Objects.toString(n.get("id")),type=Objects.toString(n.get("type"));if(!ids.add(id))issues.add(new Issue("WF_DUPLICATE_NODE",id,"节点 ID 重复",List.of()));if(NodeCatalog.get(type)==null)issues.add(new Issue("WF_UNKNOWN_NODE",id,"未知节点类型 "+type,List.of()));types.put(id,type);}var incoming=new HashMap<String,Integer>();var adj=new HashMap<String,List<String>>();ids.forEach(id->{incoming.put(id,0);adj.put(id,new ArrayList<>());});var occupied=new HashSet<String>();for(var e:edges){String s=Objects.toString(e.get("source")),t=Objects.toString(e.get("target")),sp=Objects.toString(e.getOrDefault("sourceHandle","output")),tp=Objects.toString(e.getOrDefault("targetHandle","input"));if(!ids.contains(s)||!ids.contains(t)){issues.add(new Issue("WF_EDGE_NODE_MISSING",t,"连线引用不存在的节点",List.of()));continue;}NodeCatalog.Definition sd=NodeCatalog.get(types.get(s)),td=NodeCatalog.get(types.get(t));if(sd!=null&&td!=null){var so=sd.outputs().stream().filter(x->x.name().equals(sp)).findFirst();var ti=td.inputs().stream().filter(x->x.name().equals(tp)).findFirst();if(so.isEmpty()||ti.isEmpty()||!compatible(so.map(NodeCatalog.Port::type).orElse(""),ti.map(NodeCatalog.Port::type).orElse("")))issues.add(new Issue("WF_PORT_TYPE_MISMATCH",t,"端口类型不兼容: "+sp+" → "+tp,List.of()));if(ti.isPresent()&&!ti.get().multiple()&&!occupied.add(t+":"+tp))issues.add(new Issue("WF_PORT_CARDINALITY",t,"单值输入端口不能有多条连线",List.of()));}adj.get(s).add(t);incoming.compute(t,(k,v)->v+1);}var q=new ArrayDeque<String>();incoming.forEach((k,v)->{if(v==0)q.add(k);});int count=0;while(!q.isEmpty()){String n=q.remove();count++;for(String x:adj.get(n))if(incoming.compute(x,(k,v)->v-1)==0)q.add(x);}if(count!=nodes.size())issues.add(new Issue("WF_CYCLE_DETECTED","","工作流存在环",List.of()));return issues;}
 @SuppressWarnings("unchecked") public List<String> topological(Map<String,Object> canvas){List<Map<String,Object>> nodes=(List<Map<String,Object>>)canvas.getOrDefault("nodes",List.of()),edges=(List<Map<String,Object>>)canvas.getOrDefault("edges",List.of());var in=new LinkedHashMap<String,Integer>();var adj=new HashMap<String,List<String>>();for(var n:nodes){String id=Objects.toString(n.get("id"));in.put(id,0);adj.put(id,new ArrayList<>());}for(var e:edges){String s=Objects.toString(e.get("source")),t=Objects.toString(e.get("target"));if(in.containsKey(s)&&in.containsKey(t)){adj.get(s).add(t);in.put(t,in.get(t)+1);}}var q=new ArrayDeque<String>();in.forEach((k,v)->{if(v==0)q.add(k);});var out=new ArrayList<String>();while(!q.isEmpty()){String n=q.remove();out.add(n);for(String t:adj.get(n))if(in.merge(t,-1,Integer::sum)==0)q.add(t);}if(out.size()!=nodes.size())throw new IllegalArgumentException("WF_CYCLE_DETECTED");return out;}
}
